INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z20-q93','nism-10a-z20','Health insurance is needed mainly to:','["Replace term insurance","Create wealth","Protect savings from medical expenses","Save tax only"]',2,'Medical inflation is typically higher than general inflation.',93) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z20-q94','nism-10a-z20','A goal of ₹71,00,000 is needed in 14 years. At 10% p.a. return, the lump sum to invest today is approximately:','["₹20,56,617","₹29,58,333","₹26,96,224","₹18,69,652"]',3,'PV = FV ÷ (1 + i)^n.',94) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-10a-z20-q95','nism-10a-z20','A loan of ₹15,00,000 at 9% p.a. for 10 years is repaid in monthly instalments. The EMI is approximately:','["₹21,852","₹19,001","₹23,750","₹12,500"]',1,'EMI = P·r·(1 + r)^n ÷ [(1 + r)^n − 1].',95) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
